export const buildGrade9Quiz = (prefix: string, rows: CompactQuizRow[]): HGQuizQuestion[] =>
  rows.map((r, i) => ({
    id: `${prefix}-q${String(i + 1).padStart(2, '0')}`,
    level: i < 11 ? 'basic' : i < 14 ? 'application' : 'challenge',
    prompt: r[0],
    options: [r[1], r[2], r[3], r[4]],
    answer: r[5] as 0 | 1 | 2 | 3,
    explanation: r[6]
  }));

